#!/usr/bin/env python3
import numpy as np
import os, importlib, sys
import scipy.constants as const
aulen       = const.physical_constants['atomic unit of length'][0]*1e10 # au length

class calcat():
    def __init__(self, jobname, dynamics, Energy, dynstate, ionstate, method=['gaussian', 'readenergy.txt'], tempxyz='neut_stru.xyz', force='force', vdestates = ['ani', 'vde.out'], diff='diff', init=0):
        # jobname   = [rhombus, Ag4, neut, force]   files
        # dynamics  = dynamics              dynamics
        # Energy    = Energy                Energy
        # dynstate  = neut                  dynamic state
        # ionstate  = cat                   ionized state
        # force     = force                 output files
        # method    = ['gaussian', 'readenergy.txt']    method, read energy
        # tempxyz   = 'neut_stru.xyz'       temp .xyz file from neut init geometry
        # vdestates = ['ani', '']           states for vde first, second format .com file with jobname
        # diff      = diff                  diff of neutral and cation
        # init      = 0                     prefix of the init input for frame 0 (wavefunction guess), None or '' = no init step

        self.submit = importlib.import_module('VV_8_{}'.format(method[0]))
        
        self.force = force 
        self.jobname = jobname
        self.tempcatxyz = tempxyz
        self.method = method
        self.Enname = Energy
        self.vdestates = vdestates
        self.dynE = '{}_{}.out'.format(self.jobname[0], self.Enname) 
        self.ionE = '{}{}_{}.out'.format(self.jobname[0], ionstate, self.Enname)
        self.com = '{}{}'.format(self.jobname[1], ionstate)
        self.fchk = '{}{}'.format(force, ionstate)
        self.cordf = '{}_{}.xyz'.format(self.jobname[0], dynamics)
        self.dyntraj = self.gettraj(self.cordf) # load previous trajectory)
        self.getens = whichenread(self.method, self.ionE, [0])  # self.method[1]
        self.getnames = self.getens[0][0]
        self.init = init
        for i in self.getens[1][0]:
            self.getnames.append(i)
 
        _, self.timeax, _ = loadmatrix(self.dynE)
        self.ediff = '{}_{}.out'.format(diff, self.Enname)

    def startrecalc(self):
        self.recalc(self.tempcatxyz, self.dyntraj)

    def recalc(self, xyzf, coordinates):
        time = 0
        for i in coordinates: #write .xyz file
            atoms = []
            coords = []
            N = i[0]
            for j in range(i[0]):
                atoms.append(i[j+1][0])
                coords.append(i[j+1][1])
                coords.append(i[j+1][2])
                coords.append(i[j+1][3])
            if self.init is None or self.init == '': # no init step, frame 0 is a normal calc
                self.data = self.submit.calc(self.com, self.tempcatxyz, N, atoms, coords, self.fchk, self.getnames, aulen)
            else:
                self.data = self.submit.initcalc(self.com, self.tempcatxyz, N, atoms, coords, self.fchk, self.getnames, aulen, self.init)
            os.system('date >> time.txt')
            self.write_output(self.ionE, self.timeax[time])
            break
        # write special output
        arg = 'Dip.S.'
        specarg = getlogargs('Ag4cat.log', arg)

        with open('special.out', 'w') as f:
            f.write('time[fs]\targ\n')
            f.write('{}\t{}\n'.format(self.timeax[time], specarg))

        time = 1 # frame 0 is done above, frame k is written at time axis entry k
        for i in coordinates[1:]: #write .xyz file
            atoms = []
            coords = []
            N = i[0]
            for j in range(len(i[1])):
                atoms.append(i[j+1][0])
                coords.append(i[j+1][1])
                coords.append(i[j+1][2])
                coords.append(i[j+1][3])
            self.data = self.submit.calc(self.com, self.tempcatxyz, N, atoms, coords, self.fchk, self.getnames, aulen)
            os.system('date >> time.txt')
            self.write_output(self.ionE, self.timeax[time])
            
            specarg = getlogargs('Ag4cat.log', arg)
            with open('special.out', 'a') as f:
                f.write('{}\t{}\n'.format(self.timeax[time], specarg))
            time += 1
        self.neutiondiff()

    def gettraj(self, xyzname): # read traj from dynamics.xyz
        lines = self.get_line_count(xyzname)
        read = True
        curr = 0
        with open(xyzname, 'r') as f:
            dynl = []
            while read == True:
                coord = []
                if curr+2 < lines:
                    num_atoms = int(f.readline())
                    curr += num_atoms+2
                    _ = f.readline()
                    if curr > lines: # incomplete last frame
                        read = False
                else:
                    read = False
                if read == True:
                    apl = [num_atoms]
                    for i in range(num_atoms):
                        line = f.readline().split()
                        apl.append([line[0], float(line[1])/aulen, float(line[2])/aulen, float(line[3])/aulen])
                    dynl.append(apl)
        return(dynl)
                    
    def get_line_count(self, file_path):
        with open(file_path, 'r') as f:
            lc = sum(1 for i in f)
        return lc
        
    def write_output(self, state, time): # write the requested energies into a row
        wrst = float(time)
        for i in range(len(self.getens[0][1])): # write
            if isinstance(self.data[self.getens[0][0][i]], np.ndarray):
                for j in range(self.getens[0][1][i]):
                    wrst = '{}\t{}'.format(wrst, self.data[self.getens[0][0][i]][j])
            else:
                wrst = '{}\t{}'.format(wrst, self.data[self.getens[0][0][i]])
        # no calc for cation! 
        with open(state, 'a') as f:
            f.write('{}\n'.format(wrst))
        
    def load_matrix(self, file_path): # load energy matrix
        matrix = np.loadtxt(file_path, dtype=str, delimiter='\t', skiprows=1)
        with open(file_path, 'r') as file:
            first_row = file.readline().strip().split('\t')
            header_array = np.array(first_row)
        return header_array, matrix

    def calcmatrixdiff(self, Eneut, Ecat, diffname): # calculate difference between both dynamic matrices         
        # new diff file
        nxax, nyax, ndata = loadmatrix(Eneut)
        cxax, cyax, cdata = loadmatrix(Ecat)

        if all(a == b for a, b in zip(nyax, cyax)) == False:
            print('time axis of neutral and cation are not equal')
        diffx = [nxax[0]]
        diffdata = []
    
        for j in nyax:
            diffdata.append([float(j)])
        for i in range(len(nxax)-1):
            for j in range(len(cxax)-1):
                if nxax[i+1] == cxax[j+1]:
                    diffx.append(nxax[i+1])
                    for k in range(len(ndata)):
                        diffdata[k].append(round(ndata[k][i]-cdata[k][j], 12))
        os.system('rm {}'.format(diffname))
        with open(diffname, 'w') as f:
            for i in diffx:
                f.write(i)
                f.write('\t')
            f.write('\n')
            for i in range(len(diffdata)):
                f.write('{}\n'.format('\t'.join(map(str, diffdata[i]))))                   
        
    def neutiondiff(self):
        self.calcmatrixdiff(self.dynE, self.ionE, self.ediff)#, self.timeax)

    def anic(self, dyn, free=0):
        with open(dyn) as f:
            natoms = int(f.readline())
            f.readline() # emthy line
            atoms = []
            coord = []
            for i in range(natoms):
                line = f.readline().split()
                atom_symbol, x, y, z = line[0], float(line[1])/aulen, float(line[2])/aulen, float(line[3])/aulen
                atoms.append(atom_symbol)
                coord.append(x)
                coord.append(y)
                coord.append(z)
        self.data = self.submit.calc('{}{}'.format(self.jobname[1], self.vdestates[0]), 'coord.xyz', len(atoms), atoms, coord, '{}{}'.format(self.force, self.vdestates[0]), self.getnames, aulen)
        write_axes_cation('{}{}_{}.out'.format(self.jobname[0], self.vdestates[0], self.Enname), self.getens) # (state, readen)
        self.write_output('{}{}_{}.out'.format(self.jobname[0], self.vdestates[0], self.Enname), free)
        return '{}{}_{}.out'.format(self.jobname[0], self.vdestates[0], self.Enname)
# write_output(self, state, time)
    def getvde(self):
        anicf = self.anic(self.cordf) # init for Anion calc
        vxax, vyax, vdata = loadmatrix(anicf)
        nxax, nyax, ndata = loadmatrix(self.dynE)
        vde = []
        vdxax = []
        for i in range(len(vxax)-1):
            for j in range(len(nxax)-1):
                if vxax[i+1] == nxax[j+1]:
                    vdxax.append(nxax[i+1])
                    vde.append(ndata[0][i]-vdata[0][j])
        wrst = '{}'.format(nxax[0])
        for i in vdxax:
            wrst = '{}\t{}'.format(wrst, i)
        wrst = '{}\n{}'.format(wrst, nyax[0])
        for i in vde:
            wrst = '{}\t{}'.format(wrst, i)
        with open(self.vdestates[1], 'w') as f:
            f.write(wrst)
         
def whichenread(method, state, wraxes): # init the _Energy.out file with its col-axis 
    with open(method[1]) as f:
        data = f.readlines()
    read = False
    i = 1
    appendl = 0
    readen = [[[], []], [[], []], [[], []]] # write, read, calc # note, that write is default
    quit = False
    while i < len(data) and quit == False:
        if method[0] in data[i] and read == False:
            read = True
        elif read == True:
            if data[i] == 'write:\n':
                appendl = 0
            elif data[i] == 'read:\n':
                appendl = 1
            elif data[i] == 'calc:\n':
                appendl = 2
            elif data[i] == '\n' or data[i][0] == '#':
                quit = True
                appendl = 1
            else:
                spl = data[i].split('\n')[0].split('?')
                if len(spl) == 1:
                    readen[appendl][0].append(spl[0])
                    readen[appendl][1].append(1)
                elif len(spl) == 2:
                    if spl[1] == '':
                        spl[1] = 1
                    readen[appendl][0].append(spl[0])
                    readen[appendl][1].append(int(spl[1]))
                elif len(spl) > 2:
                    print('to much deliminiters, remove ? in readen')
        i += 1
    write_axes(state, readen, wraxes)
    return readen

def get_in(ending):
    l = []
    files = os.listdir()
    for i in files:
        if ending in i:
            l.append(i)
    return l

def get_dyn_intraj(ending):
    files = os.listdir()
    for i in files:
        if ending in i:
            return i

def write_axes(state, readen, wraxes):
    wrst = 'time[fs]?0'
    for k in wraxes:
        for i in range(len(readen[k][1])):
            for j in range(readen[k][1][i]):
                wrst = '{}\t{}?{}'.format(wrst, readen[k][0][i], j)
    wrst = '{}\n'.format(wrst)
    os.system('rm {}'.format(state))
    with open(state, 'a') as f: # tried 'a' for 'w'
        f.write(wrst)

def write_axes_cation(state, readen):
    wrst = 'time[fs]?0'
    for i in range(len(readen[0][1])):
        for j in range(readen[0][1][i]):
            wrst = '{}\t{}?{}'.format(wrst, readen[0][0][i], j)
    wrst = '{}\n'.format(wrst)
    os.system('rm {}'.format(state))
    with open(state, 'a') as f: #  tried 'a' for 'w'
        f.write(wrst)

# load matrix, return: row[0, :](=ax), col[0, 1:](=time), data[col[i]:]
def loadmatrix(name):
    with open(name) as f:
        data = f.readlines()
    axis = list(filter(bool, data[0].split('\n')[0].split('\t')))
    result = []
    timeax = []
    for line in data[1:]:
        elements = line.split('\n')[0].split('\t')
        converted_line = []
        timeax.append(elements[0])
        for element in elements[1:]:
            try:
                converted_line.append(float(element))
            except ValueError:
                converted_line.append(0)
        result.append(converted_line)
    return axis, timeax, result

def rem_em_str(arr):
    return list(filter(None, arr))

def get_DipS(fchk):
    with open(fchk) as f:
        data = f.readlines()
    start = 'Ground to excited state transition electric dipole moments (Au):'
    end = 'Ground'
    read = False
    dips = [] # state, dip
    for i in range(len(data)):
        if start in data[i]:
            read = True
        elif read == True:
            if end in data[i]:
                read = False
        if read == True and len(data[i]) > 1:
            dat =  rem_em_str(data[i].split('\n')[0].split('  '))
            for i in range(len(dat)):
                if ' ' in dat[i]:
                    dat[i] = dat[i].replace(' ', '')
            if len(dat) > 1:
                dips.append(dat)
    return dips

class extdendip:
    def __init__(self, data):
        self.states = []
        for i in range(len(data)-1):
            self.states.append(int(data[i+1][0]))
        self.datas = []
        for i in range(len(data[0])-1):
            self.datas.append(data[0][i+1])
        self.data = data
        self.greparg = None
    def getarg(self, state, arg):
        self.greparg = self.data[self.states.index(state)+1][self.datas.index(arg)+1]
        return self.greparg

def getlogargs(name, arg):
    dip = get_DipS(name)
    ex = extdendip(dip)
    return ex.getarg(3, arg)


